def has_cycle_of_length(edges, new_edge, max_len):
    """Check if adding new_edge creates a cycle of length <= max_len"""
    u, v = new_edge
    # BFS from u to v, avoiding the direct edge
    # We want to find if there's a path of length 2 to max_len-1 between u and v

    # Build adjacency
    adj = {}
    for i in range(n):
        adj[i] = set()
    for (a, b) in edges:
        adj[a].add(b)
        adj[b].add(a)
    adj[u].add(v)
    adj[v].add(u)

    # BFS from u, find shortest path to v
    visited = {u}
    queue = [(u, 0)]
    while queue:
        curr, dist = queue.pop(0)
        if curr == v and dist > 0:
            return dist <= max_len
        if dist >= max_len:
            continue
        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return False

def check_girth(edges, new_edge):
    """Check if adding new_edge maintains girth >= 6"""
    u, v = new_edge

    # Check for triangles (3-cycles)
    # If u and v share a common neighbor, we have a triangle
    u_neighbors = set()
    v_neighbors = set()
    for (a, b) in edges:
        if a == u:
            u_neighbors.add(b)
        elif b == u:
            u_neighbors.add(a)
        if a == v:
            v_neighbors.add(b)
        elif b == v:
            v_neighbors.add(a)

    if u_neighbors & v_neighbors:
        return False  # Triangle exists

    # Check for 4-cycles
    # A 4-cycle through u-v would be u-x-y-v where x,y are not u,v
    # This means x is neighbor of u, y is neighbor of v, and x-y is an edge
    for x in u_neighbors:
        for y in v_neighbors:
            if x != y and (min(x,y), max(x,y)) in edges:
                return False  # 4-cycle exists

    # Check for 5-cycles
    # A 5-cycle through u-v would be u-x-y-z-v
    # Path of length 3 from u to v (not using the direct edge)
    # BFS from u to find all vertices at distance 2
    dist2_from_u = set()
    for x in u_neighbors:
        for (a, b) in edges:
            if a == x and b != u:
                dist2_from_u.add(b)
            elif b == x and a != u:
                dist2_from_u.add(a)

    # Check if any vertex at distance 2 from u is also at distance 2 from v
    # (that would create a 5-cycle u-x-y-z-v where y is the common vertex)
    dist2_from_v = set()
    for y in v_neighbors:
        for (a, b) in edges:
            if a == y and b != v:
                dist2_from_v.add(b)
            elif b == y and a != v:
                dist2_from_v.add(a)

    if dist2_from_u & dist2_from_v:
        return False  # 5-cycle exists

    return True

